//
// The device keys: one Ed25519 key per provider account, generated by WebCrypto as a
// non-extractable CryptoKey and kept in IndexedDB. The private half never exists as bytes
// anywhere the extension's code or a storage export could read it; the key signs the sign-in,
// every vote, the session refresh and the account's deletion.
//
// The sign-in nonce commits to a key before the provider says which account answers, so a
// sign-in starts with the key of the provider's account used last, and settleAccountKey then
// checks it against the account the id_token names. A key is bound to that account (a hash of
// provider and subject, never the subject itself) and serves only it: an account that comes
// back finds its own key, and with it its local id, its history and its settings.

import { toBase64Url } from "@emojery/shared/core";
import { createIdbHandle, runTransaction } from "./idb-open";

// Exported so a browser test can tear the database down by name.
export const DEVICE_KEYS_DB_NAME = "emojery-device-keys";
const STORE = "account_keys";

const db = createIdbHandle(DEVICE_KEYS_DB_NAME, 2, (d) => {
  // Version 1 held one key per provider; no released build wrote it.
  if (d.objectStoreNames.contains("keys")) d.deleteObjectStore("keys");
  if (!d.objectStoreNames.contains(STORE)) d.createObjectStore(STORE, { keyPath: "pk" });
});

interface DeviceKeyRow {
  /** The public key, base64url. */
  pk: string;
  provider: string;
  /** The account the key serves; unset until a sign-in with it names one. */
  account?: string;
  privateKey: CryptoKey;
  publicKey: Uint8Array;
  createdAt: number;
  /** When a sign-in last chose the key: the provider's newest one starts the next sign-in. */
  usedAt: number;
}

/** What leaves this module: the public key; signing goes through signWithDeviceKey. */
export interface DeviceKey {
  provider: string;
  pk: string;
  publicKey: Uint8Array;
}

const view = (row: DeviceKeyRow): DeviceKey => ({ provider: row.provider, pk: row.pk, publicKey: row.publicKey });

async function generate(provider: string, account?: string): Promise<DeviceKeyRow> {
  const pair = (await crypto.subtle.generateKey({ name: "Ed25519" }, false, ["sign", "verify"])) as CryptoKeyPair;
  const publicKey = new Uint8Array((await crypto.subtle.exportKey("raw", pair.publicKey)) as ArrayBuffer);
  const now = Date.now();
  return { pk: toBase64Url(publicKey), provider, ...(account ? { account } : {}), privateKey: pair.privateKey, publicKey, createdAt: now, usedAt: now };
}

async function readRow(pk: string): Promise<DeviceKeyRow | undefined> {
  return runTransaction(await db.open(), STORE, "readonly", "device key read aborted", (store) => {
    const req = store.get(pk);
    return () => req.result as DeviceKeyRow | undefined;
  });
}

/** A usedAt later than every row's, so the key chosen last is the newest even within one ms. */
const nextUse = (rows: DeviceKeyRow[]): number => Math.max(Date.now(), ...rows.map((r) => r.usedAt + 1));

/** Every row of the provider, read inside `store`'s transaction. */
function providerRows(store: IDBObjectStore, provider: string, then: (rows: DeviceKeyRow[]) => void): void {
  const req = store.getAll();
  req.onsuccess = () => then((req.result as DeviceKeyRow[]).filter((r) => r.provider === provider));
}

/** The key a sign-in with the provider starts with: the one chosen last, generated on first
 *  use. Two concurrent asks settle inside one transaction, so the second keeps the first one's
 *  key. */
export async function deviceKeyForSignIn(provider: string): Promise<DeviceKey> {
  const fresh = await generate(provider);
  const row = await runTransaction(await db.open(), STORE, "readwrite", "device key write aborted", (store) => {
    let kept = fresh;
    providerRows(store, provider, (rows) => {
      const newest = rows.reduce<DeviceKeyRow | undefined>((a, r) => (a && a.usedAt >= r.usedAt ? a : r), undefined);
      if (newest) kept = newest;
      else store.put(fresh);
    });
    return () => kept;
  });
  return view(row);
}

/**
 * Checks the key a sign-in used against the account the provider answered with. True when it
 * is that account's key, or a key no account has claimed yet (it is then bound to this one).
 * False when the account has another key, or the used key serves another account: the
 * account's own key, or a new one for it, becomes the provider's next key, and the sign-in
 * has to run again with it, since the nonce the provider signed names the used key.
 */
export async function settleAccountKey(provider: string, account: string, usedPk: string): Promise<boolean> {
  const fresh = await generate(provider, account);
  return runTransaction(await db.open(), STORE, "readwrite", "device key settle aborted", (store) => {
    let settled = false;
    providerRows(store, provider, (rows) => {
      const own = rows.find((r) => r.account === account);
      const used = rows.find((r) => r.pk === usedPk);
      const now = nextUse(rows);
      if (own?.pk === usedPk || (!own && used && used.account === undefined)) {
        settled = true;
        store.put({ ...(used as DeviceKeyRow), account, usedAt: now });
      } else {
        store.put(own ? { ...own, usedAt: now } : { ...fresh, usedAt: now });
      }
    });
    return () => settled;
  });
}

export async function getDeviceKey(pk: string): Promise<DeviceKey | null> {
  const row = await readRow(pk);
  return row ? view(row) : null;
}

/** A fresh key for the account `pk` served, in its place (a failed registration, a key the
 *  server holds under another account); the next sign-in with the provider starts with it. */
export async function replaceDeviceKey(provider: string, pk: string): Promise<void> {
  const old = await readRow(pk);
  const fresh = await generate(provider, old?.account);
  await runTransaction(await db.open(), STORE, "readwrite", "device key replace aborted", (store) => {
    providerRows(store, provider, (rows) => {
      store.delete(pk);
      store.put({ ...fresh, usedAt: nextUse(rows) });
    });
    return () => undefined;
  });
}

export async function dropDeviceKey(pk: string): Promise<void> {
  await runTransaction(await db.open(), STORE, "readwrite", "device key delete aborted", (store) => {
    store.delete(pk);
    return () => undefined;
  });
}

/** Ed25519 over `message` with the key `pk`; throws when there is no such key. */
export async function signWithDeviceKey(pk: string, message: Uint8Array): Promise<Uint8Array> {
  const row = await readRow(pk);
  if (!row) throw new Error("no device key for this account");
  return new Uint8Array(await crypto.subtle.sign("Ed25519", row.privateKey, message as BufferSource));
}
